40	class HixlClient {
41	 public:
42	  /**
43	   * @brief HixlClient  构造函数
44	   * @param [in] server_ip  服务端监听 IPv4 地址
45	   * @param [in] server_port  服务端监听端口号
46	   */
47	  HixlClient(const std::string &server_ip, uint32_t server_port, const ClientConfig &config)
48	      : server_ip_(server_ip),
49	        server_port_(server_port),
50	        local_engine_(config.local_engine),
51	        remote_engine_(config.remote_engine),
52	        rdma_tc_(config.rdma_tc),
53	        rdma_sl_(config.rdma_sl),
54	        qos_(config.qos),
55	        max_active_channels_(config.max_active_channels) {}
56	  ~HixlClient() = default;
57	
58	  /**
59	   * @brief 设置本端内存信息，在 BatchPut 和 BatchGet 之前需要调用
60	   * @param [in] mem_info_list 本端注册内存信息
61	   * @return 操作结果状态码
62	   */
63	  Status SetLocalMemInfo(const std::vector<MemHandleInfo> &mem_info_list);
64	
65	  /**
66	   * @brief client初始化
67	   * @param [in] local_endpoint_list 客户端本地 endpoint_list
68	   * @param [in] timeout_ms          超时时间（ms）
69	   * @param [in] is_lazy             是否懒惰建链模式
70	   * @return 操作结果状态码
71	   */
72	  Status Initialize(const std::vector<EndpointConfig> &local_endpoint_list, uint32_t timeout_ms, bool is_lazy = false);
73	
74	  /**
75	   * @brief 建链
76	   * @param [in] timeout_ms       超时时间（ms）
77	   * @return 操作结果状态码
78	   */
79	  Status Connect(uint32_t timeout_ms);
80	
81	  /**
82	   * @brief 断链&销毁
83	   * @return 操作结果状态码
84	   */
85	  Status Finalize();
86	
87	  /**
88	   * @brief 同步传输
89	   * @param [in] op_descs         批量操作的本地以及远端地址以及读取内存大小，批量操作的个数
90	   * @param [in] operation        读操作/写操作
91	   * @param [in] timeout_ms       超时时间
92	   * @return 操作结果状态码
93	   */
94	  Status TransferSync(const std::vector<TransferOpDesc> &op_descs, TransferOp operation, uint32_t timeout_ms);
95	
96	  /**
97	   * @brief 异步传输
98	   * @param [in] op_descs         批量操作的本地以及远端地址以及写入内存大小，批量操作的个数
99	   * @param [in] operation        读操作/写操作
100	   * @param [out] req             请求的handle，用于查询请求状态
101	   * @return 操作结果状态码
102	   */
103	  Status TransferAsync(const std::vector<TransferOpDesc> &op_descs, TransferOp operation,
104	                       const TransferArgs &optional_args, TransferReq &req);
105	
106	  /**
107	   * @brief 查询异步传输状态
108	   * @param [in] req             请求的handle，用于查询请求状态
109	   * @param [out] status         传输状态
110	   * @return 操作结果状态码
111	   */
112	  Status GetTransferStatus(const TransferReq &req, TransferStatus &status);
113	
114	  Status SendNotify(const NotifyDesc &notify, int32_t timeout_ms) const;
115	
116	  Status CheckAlive();
117	
118	  const std::string &GetRemoteEngine() const;
119	
120	 private:
121	  Status SendEndpointInfoReq(int32_t fd, CtrlMsgType msg_type) const;
122	  Status RecvEndpointInfoResp(int32_t fd, std::vector<EndpointConfig> &remote_endpoint_list, uint32_t timeout_ms) const;
123	  Status RecvNotifyAck(int32_t fd, int32_t timeout_ms) const;
124	  void CloseCtrlSocket();
125	  bool HasTransferReq(const TransferReq &req) const;
126	  void ClearTransferReqs();
127	  void RemoveTransferReq(const TransferReq &req);
128	  void LogLinkPairs(const char *phase) const;
129	
