199	Status HixlClient::GetTransferStatus(const TransferReq &req, TransferStatus &status) {
200	  std::lock_guard<std::mutex> lock(mutex_);
201	  if (client_handler_ == nullptr) {
202	    HIXL_LOGE(FAILED, "HixlClient is not initialized");
203	    status = TransferStatus::FAILED;
204	    return FAILED;
205	  }
206	  TransferInfo transfer_info{};
207	  auto it = req_map_.find(req);
208	  if (it == req_map_.end()) {
209	    HIXL_LOGE(PARAM_INVALID, "HixlClient GetTransferStatus failed, request not found, req:%p", req);
210	    status = TransferStatus::FAILED;
211	    return PARAM_INVALID;
212	  }
213	  transfer_info = it->second;
214	
215	  HIXL_DISMISSABLE_GUARD(dump_guard,
216	                         [this]() { client_handler_->Dump("get transfer status failed", DumpLogLevel::ERROR); });
217	  Status ret = client_handler_->GetTransferStatus(req, status);
218	  if (ret != SUCCESS) {
219	    RemoveTransferReq(req);
220	    return ret;
221	  }
222	  if (status == TransferStatus::COMPLETED) {
223	    HixlProfType type =
224	        (transfer_info.op_type == READ ? HixlProfType::HixlOpBatchRead : HixlProfType::HixlOpBatchWrite);
225	    HIXL_API_PROFILING_WITH_TIME(type, transfer_info.start_time);
226	    RemoveTransferReq(req);
227	  } else if (status == TransferStatus::FAILED) {
228	    RemoveTransferReq(req);
229	    return SUCCESS;
230	  }
231	  HIXL_DISMISS_GUARD(dump_guard);
232	  return SUCCESS;
233	}
