260	Status HixlClient::Finalize() {
261	  std::lock_guard<std::mutex> lock(mutex_);
262	  if (is_finalized_) {
263	    return SUCCESS;
264	  }
265	  is_finalized_ = true;
266	  ClearTransferReqs();
267	  HIXL_EVENT("[HixlClient] disconnect link start, local_engine:%s, remote_engine:%s", local_engine_.c_str(),
268	             remote_engine_.c_str());
269	  LogLinkPairs("disconnect link start");
270	  HIXL_DISMISSABLE_GUARD(dump_guard, [this]() {
271	    if (client_handler_ != nullptr) {
