142	std::vector<TransferReqInfo> ClientManager::GetOrderedReqs(size_t max_count) {
143	  std::vector<TransferReqInfo> reqs;
144	  std::lock_guard<std::mutex> lock(req_index_mutex_);
145	  for (auto it = ordered_reqs_.begin(); it != ordered_reqs_.end();) {
146	    const TransferReq req = *it;
147	    auto owner_it = req_to_client_.find(req);
148	    if (owner_it == req_to_client_.end()) {
149	      it = ordered_reqs_.erase(it);
150	      continue;
151	    }
152	
153	    ClientPtr client = owner_it->second.client.lock();
154	    if (client == nullptr) {
155	      req_to_client_.erase(owner_it);
156	      it = ordered_reqs_.erase(it);
157	      continue;
158	    }
159	
160	    reqs.emplace_back(TransferReqInfo{req, client, owner_it->second.user_data});
161	    ++it;
162	    if (max_count > 0 && reqs.size() >= max_count) {
163	      break;
164	    }
165	  }
166	  return reqs;
167	}
