172	    ClientPtr owner = it->second.client.lock();
173	    if (owner == nullptr || owner == client) {
174	      ordered_reqs_.erase(it->second.order_it);
175	      it = req_to_client_.erase(it);
176	    } else {
177	      ++it;
178	    }
179	  }
