15	namespace {
16	constexpr const int32_t kOptionConnectPoolThreadNum = 2;
17	constexpr const int32_t kOptionConnectPoolTaskQueueCapacity = 128;
18	
19	constexpr const int32_t kLimitThreadNumMin = 1;
20	constexpr const int32_t kLimitThreadNumMax = 64;
21	constexpr const int32_t kLimitTaskQueueCapacityMin = 1;
22	constexpr const int32_t kLimitTaskQueueCapacityMax = 65535;
23	}  // namespace
