25	ConnectPoolExecutor::ConnectPoolExecutor() {}
26	
27	ConnectPoolExecutor::~ConnectPoolExecutor() {
28	  if (is_initialized_.load(std::memory_order::memory_order_relaxed)) {
29	    Shutdown();
30	  }
31	}
