33	Status ConnectPoolExecutor::Initialize(const HixlOptions &options) {
34	  HIXL_LOGI("ConnectPoolExecutor initialize start");
35	  if (IsInitialized()) {
36	    HIXL_LOGW("ConnectPoolExecutor is already initialized");
37	    return SUCCESS;
38	  }
39	  thread_num_ = kOptionConnectPoolThreadNum;
40	  task_queue_capacity_ = kOptionConnectPoolTaskQueueCapacity;
41	  auto grc = options.GlobalResourceCfg();
42	  if (grc.has_value()) {
43	    thread_num_ = grc->connect_pool.thread_num.value_or(kOptionConnectPoolThreadNum);
44	    task_queue_capacity_ = grc->connect_pool.task_queue_capacity.value_or(kOptionConnectPoolTaskQueueCapacity);
45	  }
46	  HIXL_CHK_BOOL_RET_STATUS(thread_num_ >= kLimitThreadNumMin && thread_num_ <= kLimitThreadNumMax, PARAM_INVALID,
47	                           "thread_num:%d must in [%d, %d]", thread_num_, kLimitThreadNumMin, kLimitThreadNumMax);
48	  HIXL_CHK_BOOL_RET_STATUS(
49	      task_queue_capacity_ >= kLimitTaskQueueCapacityMin && task_queue_capacity_ <= kLimitTaskQueueCapacityMax,
50	      PARAM_INVALID, "task_queue_capacity:%d must in [%d, %d]", task_queue_capacity_, kLimitTaskQueueCapacityMin,
51	      kLimitTaskQueueCapacityMax);
52	
53	  HIXL_CHK_STATUS_RET(ctx_.GetCurrentContext(), "Failed to capture acl context");
54	  is_initialized_.store(true, std::memory_order::memory_order_relaxed);
55	  for (int32_t i = 0; i < thread_num_; ++i) {
56	    workers_.emplace_back([this, i]() { WorkerHandler(i); });
57	  }
58	  HIXL_LOGI("ConnectPoolExecutor initialize success");
59	  return SUCCESS;
60	}
